"""Editorial source: one page per distinct service or project intent."""
PAGES = [
('servicos','gesseiro-em-sao-paulo','Gesseiro em São Paulo',
 'Serviços de gesso em São Paulo para obras residenciais e comerciais. Conheça forros, sancas e acabamentos da MC Gesso e solicite uma avaliação.',
 'Da definição do forro ao acabamento das juntas, o trabalho do gesseiro precisa acompanhar o projeto e as condições de cada imóvel. A MC Gesso reúne soluções em construção a seco para residências, empresas e redes comerciais em São Paulo.',
 [('O que considerar ao contratar um gesseiro','Antes de comparar propostas, descreva quais ambientes serão atendidos e se a obra envolve forro, sanca, divisória ou acabamento. Informe também se existem projetos de arquitetura e iluminação. Um orçamento precisa deixar claros a metragem, os materiais, o preparo do local e as etapas de entrega.'),
 ('Gesso tradicional ou sistema em drywall?','A escolha depende do tipo de aplicação, das instalações previstas e do acabamento desejado. Tetos e paredes têm necessidades diferentes de estrutura e fixação. Em vez de escolher apenas pelo preço do metro quadrado, vale avaliar o conjunto do sistema e a compatibilidade com o ambiente.'),
 ('Como organizar a execução em São Paulo','Em apartamentos e condomínios, as regras de acesso, elevador e horário de obra influenciam a programação. Em lojas e escritórios, é necessário considerar circulação de pessoas e outras equipes. Envie essas informações no primeiro contato para que a proposta considere as condições reais da obra.')],
 [('O gesseiro também instala divisórias?','A MC Gesso trabalha com paredes e divisórias em drywall, além de forros e detalhes em gesso. O sistema adequado depende do projeto.'),('O orçamento depende apenas da metragem?','Não. Altura, recortes, estrutura, acesso, detalhes e acabamento também interferem no escopo e no valor.')]),
('servicos','drywall-em-sao-paulo','Drywall em São Paulo',
 'Instalação de drywall em São Paulo para paredes, divisórias e forros. Soluções da MC Gesso para ambientes residenciais e comerciais. Peça orçamento.',
 'O drywall permite reorganizar ambientes com paredes e forros estruturados a partir de perfis e chapas de gesso. A MC Gesso atende projetos em São Paulo que precisam conciliar distribuição dos espaços, passagem de instalações e acabamento.',
 [('Aplicações para residências e empresas','Paredes internas, divisórias, fechamentos técnicos e forros são aplicações distintas do sistema. No ambiente residencial, a solução pode organizar quartos e áreas de trabalho. No comercial, pode compor salas de reunião, áreas administrativas e setores de atendimento.'),
 ('Especificação antes da montagem','A composição precisa considerar altura, uso do espaço, umidade e cargas que serão fixadas. Armários, bancadas e equipamentos exigem previsão de reforços e fixações adequadas. Informe esses itens antes do fechamento das chapas para evitar adaptações posteriores.'),
 ('Juntas e acabamento fazem parte do sistema','Perfis, chapas, parafusos e tratamento de juntas trabalham em conjunto. O planejamento deve incluir interferências elétricas e hidráulicas e o acabamento previsto. Para comparar orçamentos, confira se as propostas contemplam a mesma composição e a mesma etapa final de entrega.')],
 [('Drywall pode receber armários?','Pode, desde que cargas, reforços e fixações sejam dimensionados para o uso. Informe o mobiliário antes da execução.'),('Toda parede de drywall tem o mesmo isolamento acústico?','Não. O desempenho depende da composição, do preenchimento, das juntas e das transmissões de som pelo restante do ambiente.')]),
('servicos','forro-de-gesso-em-sao-paulo','Forro de gesso em São Paulo',
 'Forro de gesso em São Paulo com planejamento de rebaixamento, iluminação e instalações. Conheça as soluções da MC Gesso para seu projeto.',
 'O forro de gesso organiza o teto e permite integrar iluminação e instalações ao desenho do ambiente. Para obras em São Paulo, a MC Gesso avalia a solução de rebaixamento conforme o pé-direito e os detalhes previstos no projeto.',
 [('Altura e interferências do teto','A altura final depende da estrutura, das instalações existentes e dos equipamentos que ficarão acima do forro. Antes de definir o rebaixamento, confira vigas, tubulações, climatização e espaço para luminárias. Essas informações orientam o desenho do teto.'),
 ('Escolha dos detalhes de acabamento','Forro tabicado, cortineiro e sanca têm funções e efeitos visuais diferentes. A tabica marca o encontro com as paredes; o cortineiro acomoda a cortina; a sanca pode trabalhar com iluminação indireta. A combinação deve seguir a proporção do ambiente e o projeto de interiores.'),
 ('O que enviar para solicitar uma proposta','Envie as medidas aproximadas, fotos do teto atual, bairro do imóvel e planta, quando disponível. Indique os pontos de iluminação e a presença de ar-condicionado. A confirmação das condições de fixação e das interferências faz parte da definição técnica do serviço.')],
 [('Forro de gesso reduz a altura do ambiente?','Sim. O rebaixamento necessário depende da estrutura e das instalações previstas, devendo ser verificado no projeto.'),('A iluminação precisa ser definida antes?','É recomendável definir posições, recortes e equipamentos antes da montagem para compatibilizar o forro e as instalações.')]),
('servicos','sanca-de-gesso-em-sao-paulo','Sanca de gesso em São Paulo',
 'Sanca de gesso em São Paulo para salas, quartos e espaços comerciais. Planeje iluminação indireta e acabamento com a MC Gesso. Solicite avaliação.',
 'A sanca de gesso cria um detalhe entre o teto e as paredes e pode compor a iluminação do ambiente. A MC Gesso executa soluções em São Paulo com desenho alinhado ao projeto arquitetônico e às proporções do espaço.',
 [('Sanca aberta, fechada ou invertida','Os modelos diferem pela forma e pela direção da abertura. A aberta pode acomodar iluminação indireta; a fechada tem outra relação com os pontos de luz; a invertida trabalha o efeito junto ao perímetro. A escolha precisa considerar o resultado desejado e o teto existente.'),
 ('Dimensões que combinam com o ambiente','Largura, altura e extensão da sanca influenciam o volume percebido no teto. Em salas compactas, detalhes excessivos podem pesar na composição. Em ambientes amplos, o desenho pode ajudar a delimitar usos sem criar novas paredes.'),
 ('Integração com iluminação e cortinas','Posições de luminárias, perfis e cortineiros precisam ser coordenadas. Acesso a fontes e manutenção também deve ser previsto quando houver LED. Envie uma referência visual junto das medidas para discutir o efeito desejado antes de definir o escopo.')],
 [('Sanca e rebaixamento são a mesma coisa?','Não. O rebaixamento modifica a altura do teto em uma área; a sanca é um detalhe que pode integrar esse forro ou compor parte do perímetro.'),('Posso escolher a sanca por uma foto?','A foto ajuda a comunicar a referência, mas dimensões e viabilidade precisam ser adaptadas ao ambiente.')]),
('solucoes','forro-de-gesso-para-apartamento-em-sao-paulo','Forro de gesso para apartamento em São Paulo',
 'Forro de gesso para apartamento em São Paulo: planeje altura, iluminação e regras de condomínio com a MC Gesso. Solicite orçamento para sua obra.',
 'Rebaixar o teto de um apartamento exige compatibilizar o projeto de interiores com as instalações e as regras do condomínio. A MC Gesso trabalha essa solução em São Paulo considerando as condições de cada unidade.',
 [('Pé-direito e integração dos cômodos','Sala, corredor e dormitórios podem precisar de alturas ou detalhes diferentes. A planta ajuda a decidir onde manter continuidade e onde criar uma transição. A avaliação do teto atual evita definir um desenho incompatível com vigas ou tubulações.'),
 ('Condomínio e sequência da reforma','Horários de trabalho, uso do elevador e descarte de resíduos precisam entrar no planejamento. A montagem também deve ser coordenada com elétrica, climatização e marcenaria. Consulte a administração sobre documentos e regras aplicáveis antes de iniciar a obra.'),
 ('Uma proposta adaptada ao apartamento','Informe se a unidade está ocupada, quais cômodos serão atendidos e quando pretende executar. Fotos e medidas ajudam na análise inicial. Cortineiros, recortes e pontos de acesso devem estar descritos na proposta para que o acabamento corresponda ao desenho aprovado.')],
 [('É possível fazer forro só na sala?','Sim, desde que a solução seja compatível com o ambiente e com as instalações. Não é necessário rebaixar todo o apartamento.'),('A reforma precisa seguir regras do condomínio?','Sim. Confirme previamente horários, acesso, documentação e condições para execução com a administração.')]),
('solucoes','forro-de-gesso-tabicado-em-sao-paulo','Forro de gesso tabicado em São Paulo',
 'Forro de gesso tabicado em São Paulo com acabamento perimetral para projetos residenciais e comerciais. Conheça a solução e consulte a MC Gesso.',
 'O forro tabicado se caracteriza pelo detalhe de separação no encontro com as paredes. Esse acabamento cria uma linha de sombra no perímetro e pede atenção ao alinhamento e à regularidade das superfícies.',
 [('O detalhe da tabica no projeto','A tabica faz parte da solução de encontro do forro com as paredes. Seu desenho e sua instalação devem acompanhar o sistema especificado. A linha aparente precisa ser considerada junto da pintura e dos outros detalhes do teto.'),
 ('Compatibilidade com paredes e marcenaria','Paredes fora de alinhamento podem se tornar mais perceptíveis junto à linha da tabica. Armários altos, painéis e cortineiros também interferem nesse encontro. Avaliar essas interfaces antes da montagem ajuda a definir uma composição coerente.'),
 ('Informações para o orçamento','Indique a área do forro, altura aproximada, desenho do perímetro e posição dos cortineiros. Detalhes de iluminação e recortes devem aparecer no escopo. Na comparação de propostas, confira o tipo de sistema e o acabamento incluído.')],
 [('Forro tabicado dispensa tratamento de juntas?','Não. As juntas entre chapas continuam exigindo tratamento adequado. A tabica corresponde ao detalhe do perímetro.'),('A tabica pode acompanhar um cortineiro?','A combinação pode ser prevista no projeto, com detalhamento dos encontros e espaço necessário para a cortina.')]),
('solucoes','cortineiro-de-gesso-com-led-em-sao-paulo','Cortineiro de gesso com LED em São Paulo',
 'Cortineiro de gesso com LED em São Paulo: integração entre teto, cortina e iluminação. Planeje o detalhe do seu ambiente com a MC Gesso.',
 'O cortineiro embutido reserva espaço para trilhos e cortinas; a iluminação em LED acrescenta um efeito ao conjunto. Para a execução em São Paulo, a MC Gesso considera o espaço disponível e o desenho definido para o teto.',
 [('Espaço para trilho e movimento da cortina','A largura do nicho depende do tipo de trilho, das camadas de tecido e de interferências próximas à janela. Cortinas motorizadas também podem exigir espaço e alimentação específicos. Essas definições devem anteceder o fechamento do gesso.'),
 ('Iluminação com acesso para manutenção','O efeito depende da posição do LED e da superfície iluminada. Preveja dissipação, acesso aos componentes e coordenação com a equipe elétrica. A execução do gesso deve acompanhar a especificação dos equipamentos, sem bloquear pontos que precisem de manutenção.'),
 ('Como descrever seu cortineiro','Envie a largura da janela, fotos do teto e referência da cortina. Informe se o imóvel já tem forro e se haverá substituição do trilho. A proposta deve esclarecer o serviço de gesso e quais etapas de elétrica e instalação da cortina estão incluídas ou serão executadas por outras equipes.')],
 [('O cortineiro precisa atravessar toda a parede?','Não necessariamente. O comprimento depende da composição desejada e da posição da cortina.'),('O orçamento inclui fita de LED e instalação elétrica?','Esses itens precisam ser discriminados na proposta. Confirme o escopo de gesso e os serviços complementares antes de contratar.')]),
('solucoes','divisoria-de-drywall-para-escritorio-em-sao-paulo','Divisória de drywall para escritório em São Paulo',
 'Divisória de drywall para escritório em São Paulo. Organize salas de reunião, atendimento e áreas de trabalho com a MC Gesso. Solicite orçamento.',
 'Divisórias de drywall ajudam a distribuir salas e setores de um escritório. A MC Gesso atende projetos corporativos em São Paulo com atenção à circulação, às instalações e ao uso de cada ambiente.',
 [('Layout antes da montagem','A posição das divisórias deve considerar portas, acessibilidade, mobiliário e caminhos de circulação. Salas de reunião e postos de trabalho também têm necessidades diferentes de rede e energia. Um layout definido evita mudanças depois do fechamento das chapas.'),
 ('Privacidade depende do conjunto','O isolamento não depende apenas da parede. Portas, encontros com o forro, vãos e passagens de instalações podem transmitir som. Para espaços que exigem privacidade, a especificação deve avaliar essas interfaces e a composição do sistema.'),
 ('Execução em escritório ocupado','Informe se a empresa continuará funcionando durante a obra. A programação precisa considerar proteção, circulação e coordenação com outras equipes. O orçamento deve explicitar metragem, vãos de portas, reforços e estágio de acabamento previsto.')],
 [('É possível prever tomadas nas divisórias?','Sim. As posições e os caminhos das instalações precisam ser coordenados antes de fechar as chapas.'),('Toda divisória garante privacidade de uma reunião?','Não. O resultado depende da parede, das portas, do forro e das demais transmissões de som, exigindo avaliação do conjunto.')]),
('solucoes','drywall-para-lojas-em-sao-paulo','Drywall para lojas em São Paulo',
 'Drywall para lojas em São Paulo: paredes, forros e fechamentos alinhados ao projeto comercial. Conheça a atuação da MC Gesso para lojas e franquias.',
 'Lojas e franquias precisam coordenar acabamento, identidade visual e instalações dentro de um cronograma de obra. A MC Gesso atua em São Paulo com soluções de drywall para projetos comerciais.',
 [('Projeto comercial e padrão da rede','Paredes, forros e fechamentos precisam acompanhar o layout e as especificações da arquitetura. Em franquias, o manual da marca pode definir detalhes de iluminação, alturas e acabamentos. Compartilhe esses documentos para que a proposta considere o padrão necessário.'),
 ('Reforços para mobiliário e comunicação','Expositores, painéis, prateleiras e equipamentos podem gerar cargas nos fechamentos. As posições devem ser informadas antes da montagem para definir reforços e fixações. Passagens de instalações e acessos técnicos também precisam estar compatibilizados.'),
 ('Coordenação com a operação do imóvel','Shopping centers e condomínios comerciais têm regras próprias de acesso, documentação e horários. O planejamento deve integrar montagem, elétrica, climatização e mobiliário. Prazos e condições de trabalho precisam ser acordados com base no escopo aprovado.')],
 [('A MC Gesso atende projetos de franquias?','O atendimento a lojas e redes de franquias integra a apresentação institucional da MC Gesso. Envie o projeto e a localização para avaliar o escopo.'),('É possível definir o prazo antes de analisar o projeto?','O cronograma depende da área, dos detalhes, das instalações e das regras do imóvel. A análise do projeto orienta a programação.')]),
('solucoes','parede-de-drywall-com-isolamento-acustico-em-sao-paulo','Parede de drywall com isolamento acústico em São Paulo',
 'Parede de drywall com isolamento acústico em São Paulo para ambientes residenciais e comerciais. Consulte a MC Gesso sobre composição e execução.',
 'O desempenho acústico de uma parede de drywall depende da composição e das condições do ambiente. A MC Gesso trabalha com soluções de paredes e preenchimento em lã mineral, conforme as necessidades do projeto em São Paulo.',
 [('Defina qual ruído precisa ser tratado','Conversas entre salas, equipamentos e ruídos externos são situações diferentes. Descreva a origem do incômodo e o uso dos ambientes. O diagnóstico ajuda a avaliar se a parede é o caminho principal de transmissão ou se existem outras interfaces relevantes.'),
 ('Chapas, estrutura e preenchimento','Número de chapas, perfis, preenchimento e vedação influenciam o desempenho. A solução deve ser especificada como um sistema, com atenção às juntas e às passagens de instalações. Uma composição adequada em catálogo também precisa ser executada corretamente em obra.'),
 ('Portas e forros também importam','O som pode passar por portas, frestas e espaços acima do forro. Por isso, tratar uma parede isoladamente pode não resolver todo o problema. Compartilhe planta, fotos e descrição do uso para discutir as limitações e o escopo da intervenção.')],
 [('A parede elimina todo o som?','Não se deve prometer eliminação total. O desempenho depende do sistema e dos caminhos de transmissão no imóvel.'),('Lã mineral substitui o tratamento das juntas?','Não. Preenchimento, chapas, estrutura e vedação têm funções complementares e precisam seguir a especificação do sistema.')])
]
